SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, i.intime, i.outtime, i.los, CASE WHEN i.careunit IS NOT NULL THEN 'Yes' ELSE 'No' END AS icu_admission, COUNT(d.icd_code) AS num_diagnoses, AVG(d.value) AS avg_diagnostic_value FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays i ON a.stay_id = i.stay_id JOIN chartevents c ON a.hadm_id = c.hadm_id AND a.stay_id = c.stay_id JOIN diagnoses_icd d ON c.itemid = d.icd_code AND c.charttime BETWEEN d.diag_time_start AND d.diag_time_end WHERE p.gender = 'F' AND p.anchor_age BETWEEN 78 AND 88 AND d.icd_code IN ('V65.0', 'V65.1', 'V65.2', 'V65.3', 'V65.4') AND c.valueuom NOT ILIKE '%invasive%' GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, i.intime, i.outtime, i.los, icu_admission ORDER BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, i.intime, i.outtime, i.los, icu_admission NULLS LAST;